using System;

class BasicTryCatch
{
    static void Main()
    {
        try
        {
            Console.Write("Enter a number: ");
            string input = Console.ReadLine();
            int number = int.Parse(input);
            Console.WriteLine($"You entered: {number}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
            Console.WriteLine("Please try again and enter a valid number.");
        }

        Console.WriteLine("Program continues running...");
    }
}

using System;
using System.IO;

class MultipleCatches
{
    static void ProcessFile(string path)
    {
        try
        {
            string content = File.ReadAllText(path);
            int number = int.Parse(content);
            int result = 100 / number;
            Console.WriteLine($"Result: {result}");
        }
        catch (FileNotFoundException ex)
        {
            Console.WriteLine($"File not found: {ex.FileName}");
        }
        catch (DirectoryNotFoundException ex)
        {
            Console.WriteLine($"Directory not found: {ex.Message}");
        }
        catch (FormatException ex)
        {
            Console.WriteLine("File content is not a valid number");
        }
        catch (DivideByZeroException ex)
        {
            Console.WriteLine("Cannot divide by zero");
        }
        catch (IOException ex)
        {
            Console.WriteLine($"I/O error: {ex.Message}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Unexpected error: {ex.Message}");
        }
    }
}

using System;

class ExceptionVariableDemo
{
    static void ParseAge(string input)
    {
        try
        {
            int age = int.Parse(input);
            Console.WriteLine($"Age: {age}");
        }
        catch (FormatException ex)
        {
            // ex is the actual exception object
            Console.WriteLine($"Invalid format: '{ex.Message}'");
            Console.WriteLine($"Param name in message: '{ex.ParamName}'");
        }
        catch (OverflowException ex)
        {
            Console.WriteLine($"Number too large: {ex.Message}");
        }
    }
}

using System;
using System.IO;

class FinallyDemo
{
    static void ReadFirstLine(string path)
    {
        StreamReader? reader = null;

        try
        {
            reader = new StreamReader(path);
            string? line = reader.ReadLine();
            Console.WriteLine($"First line: {line}");
        }
        catch (FileNotFoundException ex)
        {
            Console.WriteLine($"File not found: {ex.FileName}");
        }
        catch (IOException ex)
        {
            Console.WriteLine($"Read error: {ex.Message}");
        }
        finally
        {
            // This ALWAYS runs — even if an exception occurred
            reader?.Dispose();
            Console.WriteLine("Reader closed in finally block");
        }
    }
}

using System;
using System.IO;

class UsingStatementDemo
{
    static void ReadFirstLineClean(string path)
    {
        // 'using' ensures Dispose() is called automatically
        try
        {
            using var reader = new StreamReader(path);
            string? line = reader.ReadLine();
            Console.WriteLine($"First line: {line}");
        }
        catch (FileNotFoundException ex)
        {
            Console.WriteLine($"File not found: {ex.FileName}");
        }
    }

    static void ProcessMultipleFiles(string[] paths)
    {
        // Classic using statement with braces
        foreach (string path in paths)
        {
            using (var reader = new StreamReader(path))
            {
                string content = reader.ReadToEnd();
                Console.WriteLine($"{path}: {content.Length} chars");
            }
        }
    }
}

using System;

class ExceptionFilters
{
    static void Divide(int a, int b)
    {
        try
        {
            int result = a / b;
            Console.WriteLine($"{a} / {b} = {result}");
        }
        catch (DivideByZeroException ex) when (b == 0)
        {
            Console.WriteLine("The divisor was zero — caught by filter");
        }
        catch (DivideByZeroException)
        {
            Console.WriteLine("Generic divide-by-zero handler");
        }
    }

    static void LogErrors(Exception ex)
    {
        if (ex is IOException)
        {
            Console.WriteLine("File or stream error occurred");
        }
    }
}

using System;

class RethrowDemo
{
    // CORRECT: preserves original stack trace
    static void CorrectRethrow(string path)
    {
        try
        {
            ProcessFile(path);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Logging error: {ex.Message}");
            throw; // Re-throws with ORIGINAL stack trace intact
        }
    }

    // WRONG: resets stack trace
    static void WrongRethrow(string path)
    {
        try
        {
            ProcessFile(path);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Logging error: {ex.Message}");
            throw ex; // Stack trace now points HERE — bad for debugging!
        }
    }

    static void ProcessFile(string path)
    {
        // This is where the error actually happens
        throw new FileNotFoundException(path);
    }
}
